%% =====================================================================
%%  WEB USER INTERFACE
%%  HTML pages generated by Prolog and served by the SWI-Prolog HTTP server.
%% =====================================================================

num(F, Name, Lo, Hi, Label) :-
    (   memberchk(Name = Raw, F), atom_number(Raw, N), number(N), N >= Lo, N =< Hi
    ->  assertz(known(Name, N))
    ;   format(atom(Msg), "~w must be a number between ~w and ~w.", [Label, Lo, Hi]),
        throw(bad(Msg))
    ).

choice(F, Name, Opts, Label) :-
    (   memberchk(Name = V, F), memberchk(V, Opts)
    ->  assertz(known(Name, V))
    ;   format(atom(Msg), "Please answer the question: ~w", [Label]),
        throw(bad(Msg))
    ).

read_inputs(F) :-
    num(F, age, 1, 120, 'Age'),
    choice(F, sex, [male, female], 'Sex'),
    choice(F, first_time, [yes, no], 'First-time donor'),
    (   known(first_time, yes)
    ->  assertz(known(months_since_last, 999))
    ;   num(F, months_since_last, 0, 1200, 'Months since last donation')
    ),
    num(F, weight_kg, 20, 250, 'Weight'),
    num(F, haemoglobin, 3, 25, 'Haemoglobin'),
    (   known(sex, female)
    ->  choice(F, pregnant, [yes, no], 'Pregnant')
    ;   assertz(known(pregnant, no))
    ),
    choice(F, serious_illness, [yes, no], 'Serious medical illness'),
    choice(F, epilepsy, [yes, no], 'History of epilepsy'),
    choice(F, risk_behaviour, [yes, no], 'Risk behaviours'),
    choice(F, valid_id, [yes, no], 'Valid ID'),
    (   memberchk(travel_country = C, F), ( memberchk(C, [none, other, unsure]) ; malaria_endemic(C) )
    ->  assertz(known(travel_country, C))
    ;   throw(bad('Please choose a travel option.'))
    ),
    (   ( known(travel_country, none) ; known(travel_country, unsure) )
    ->  assertz(known(months_since_return, 999))
    ;   num(F, months_since_return, 0, 1200, 'Months since return from travel')
    ).

