nav_active('Knowledge Base', rules).
nav_active('Test Cases',     tests).

%% link_text(+Text, -Html): escape Text and turn any https:// URL in it into a clickable link.
link_text(T, Out) :-
    format(atom(A), "~w", [T]),
    (   once(sub_atom(A, B, _, _, 'https://'))
    ->  sub_atom(A, 0, B, _, Pre0),
        sub_atom(A, B, _, 0, Url),
        (   atom_concat(Pre, ' - ', Pre0) -> true ; Pre = Pre0 ),
        esc(Pre, QP), esc(Url, QU),
        format(atom(Out), "~w - <a href='~w' target='_blank' rel='noopener'>~w</a>", [QP, QU, QU])
    ;   esc(A, Out)
    ).

page_start(Title) :-
    format("Content-type: text/html; charset=UTF-8~n~n"),
    w("<!DOCTYPE html><html><head><meta charset='utf-8'>"),
    w("<meta name='viewport' content='width=device-width, initial-scale=1'>"),
    format("<title>~w</title><style>~n", [Title]),
    forall(css(L), w(L)),
    w("</style></head><body>"),
    w("<header><h1>&#129656; Blood Donor Eligibility Expert System</h1>"),
    w("<p>Based on the National Blood Transfusion Service (NBTS), Sri Lanka criteria</p></header>"),
    ( nav_active(Title, Cur) -> true ; Cur = home ),
    w("<nav>"),
    forall(nav_item(Id, Href, Label),
           (   Id == Cur
           ->  format("<a class='active' aria-current='page' href='~w'>~w</a>~n", [Href, Label])
           ;   format("<a href='~w'>~w</a>~n", [Href, Label])
           )),
    w("</nav>"),
    ( memberchk(Title, ['Knowledge Base', 'Test Cases']) -> w("<main class='wide'>") ; w("<main>") ).

page_end :-
    w("<p><small>Educational prototype. The final decision is always made by NBTS medical staff at the donation centre.</small></p>"),
    w("</main>"),
    w("<footer>Criteria source: <a href='https://nbts.health.gov.lk/donate-blood/' target='_blank' rel='noopener'>NBTS Sri Lanka</a> &middot; Built with SWI-Prolog</footer>"),
    w("</body></html>").

%% ---------------- Home page : hero + step-by-step questionnaire ----------------
page_home(_Request) :-
    page_start('Blood Donor Eligibility'),
    aggregate_all(count, rule(_, _, _, _, _), NR),
    w("<section class='hero' id='hero'><div class='drop'>&#129656;</div><h2>Can I donate blood?</h2>"),
    w("<p>Answer a few quick questions. The expert system checks them against the official NBTS Sri Lanka criteria and explains exactly how it reached its decision.</p>"),
    format("<div class='chips'><span>~w rules</span><span>Forward + backward chaining</span><span>Source: NBTS Sri Lanka</span></div>~n", [NR]),
    w("<button onclick='startQ()'>Start the check</button></section>"),
    w("<section id='how' class='steps3'><div><span class='ic'>&#128221;</span><b>1. Answer</b><p>Short questions, one at a time. Takes about a minute.</p></div><div><span class='ic'>&#9881;</span><b>2. Rules fire</b><p>Forward chaining applies the NBTS rules to your answers.</p></div><div><span class='ic'>&#9989;</span><b>3. Get an explained result</b><p>See a checklist and a proof of how the decision was made.</p></div></section>"),
    w("<section class='card hide' id='wiz'><div class='bar'><div id='bar'></div></div><small id='cnt'></small><h2 id='qt'></h2><div id='qa'></div><div class='err' id='er' role='alert'></div><button class='ghost' onclick='back()'>Back</button></section>"),
    w("<script>var C=["),
    setof(C, malaria_endemic(C), Cs),
    forall(member(C, Cs), format("\"~w\",~n", [C])),
    w("];"),
    w("var yn=[['no','No'],['yes','Yes']];"),
    w("var Q=[{id:'age',t:'How old are you?',k:'n',min:1,max:120,u:'age in years'},"),
    w("{id:'sex',t:'What is your sex?',k:'o',o:[['male','Male'],['female','Female']]},"),
    w("{id:'weight_kg',t:'What is your weight?',k:'n',min:20,max:250,u:'weight in kg',s:'0.1'},"),
    w("{id:'haemoglobin',t:'What is your haemoglobin level?',k:'n',min:3,max:25,u:'g/dL',s:'0.1'},"),
    w("{id:'first_time',t:'Is this your first blood donation?',k:'o',o:[['yes','Yes, my first time'],['no','No, I have donated before']]},"),
    w("{id:'months_since_last',t:'How many months since your last donation?',k:'n',min:0,max:1200,u:'months',f:function(){return A.first_time=='no'}},"),
    w("{id:'pregnant',t:'Are you pregnant?',k:'o',o:yn,f:function(){return A.sex=='female'}},"),
    w("{id:'serious_illness',t:'Do you have a serious medical illness?',k:'o',o:yn},"),
    w("{id:'epilepsy',t:'Do you have a history of epilepsy?',k:'o',o:yn},"),
    w("{id:'risk_behaviour',t:'Do you have any NBTS risk behaviours? (ask NBTS staff if unsure)',k:'o',o:yn},"),
    w("{id:'valid_id',t:'Do you have a National Identity Card or other valid ID?',k:'o',o:[['yes','Yes'],['no','No']]},"),
    w("{id:'travel_country',t:'Have you travelled abroad recently?',k:'s'},"),
    w("{id:'months_since_return',t:'How many months since you returned to Sri Lanka?',k:'n',min:0,max:1200,u:'months',f:function(){return A.travel_country&&A.travel_country!='none'&&A.travel_country!='unsure'}}];"),
    w("var A={},i=0;"),
    w("function $(x){return document.getElementById(x)}"),
    w("function el(t,c,x){var e=document.createElement(t);if(c)e.className=c;if(x!==undefined)e.textContent=x;return e}"),
    w("function vis(){return Q.filter(function(q){return !q.f||q.f()})}"),
    w("function startQ(){$('how').style.display='none';$('hero').className='hide';$('wiz').className='card';show()}"),
    w("function back(){if(i>0){i--;show()}else{$('wiz').className='card hide';$('hero').className='hero';$('how').style.display=''}}"),
    w("function nextN(q,inp){var v=parseFloat(inp.value);if(isNaN(v)||v<q.min||v>q.max){$('er').textContent='Please enter a number between '+q.min+' and '+q.max;return}A[q.id]=v;i++;show()}"),
    w("function show(){var v=vis();if(i>=v.length){go();return}var q=v[i],qa=$('qa');qa.innerHTML='';var wz=$('wiz');wz.classList.remove('in');void wz.offsetWidth;wz.classList.add('in');$('er').textContent='';"),
    w("$('bar').style.width=(i/v.length*100)+'%';$('cnt').textContent='Question '+(i+1)+' of '+v.length;$('qt').textContent=q.t;"),
    w("if(q.k=='o'){q.o.forEach(function(o){var b=el('button','tile',o[1]);b.onclick=function(){A[q.id]=o[0];i++;show()};qa.appendChild(b)});return}"),
    w("var inp;if(q.k=='n'){inp=el('input');inp.type='number';inp.step=q.s||'1';inp.placeholder=q.u}"),
    w("else{inp=el('select');[['none','No foreign travel'],['other','Yes - to a country NOT on the malaria-endemic list'],['unsure','I am not sure']].concat(C.map(function(c){return [c,c+' (malaria-endemic)']})).forEach(function(o){inp.add(new Option(o[1],o[0]))})}"),
    w("if(A[q.id]!==undefined)inp.value=A[q.id];qa.appendChild(inp);inp.focus();"),
    w("var b=el('button','','Next');function nx(){if(q.k=='n')nextN(q,inp);else{A[q.id]=inp.value;i++;show()}}b.onclick=nx;inp.onkeydown=function(e){if(e.key=='Enter')nx()};qa.appendChild(b)}"),
    w("function go(){var p=vis().map(function(q){return q.id+'='+encodeURIComponent(A[q.id])});location.href='/assess?'+p.join('&')}"),
    w("</script>"),
    page_end.

%% ---------------- Result page ----------------
page_assess(Request) :-
    http_parameters(Request, [], [form_data(Form)]),
    clear_wm,
    (   catch(read_inputs(Form), bad(Msg), ( show_error(Msg), fail ))
    ->  run_forward, show_result
    ;   true
    ).

show_error(Msg) :-
    page_start('Input error'),
    esc(Msg, Q),
    format("<div class='card bad'><h2>Please check your input</h2><p>~w</p><p><a href='/'>Go back</a></p></div>~n", [Q]),
    page_end.

show_result :-
    known(status, S),
    page_start('Result'),
    verdict(S),
    checklist,
    ( S == eligible -> advice_box ; true ),
    explanation(S),
    page_end.

verdict_style(eligible,     ok,   '&#10003;', 'You appear to be ELIGIBLE to donate blood', 'All NBTS basic criteria are satisfied based on your answers.').
verdict_style(not_eligible, bad,  '&#10007;', 'You are NOT eligible to donate blood at this time', 'One or more NBTS criteria are not met.').
verdict_style(refer_nbts,   warn, '?',        'Please ask NBTS staff before donating', 'You are unsure about your travel history. NBTS advises asking their staff or contacting them before donating.').

verdict(S) :-
    verdict_style(S, Cls, Icon, Title, Sub),
    format("<section class='hero2 ~w'><div class='big'>~w</div><div><h2>~w</h2><p>~w</p></div></section>~n", [Cls, Icon, Title, Sub]),
    forall(( known(deferral, C), deferral_info(C, _, T) ),
           ( esc(T, Q), format("<div class='reason'>~w</div>~n", [Q]) )).

checklist :-
    aggregate_all(count, criterion(_, _), Tot),
    aggregate_all(count, ( criterion(K0, _), known(passed, K0) ), Ok),
    Pct is round(Ok * 100 / max(Tot, 1)),
    w("<div class='card'><h2>Eligibility checklist</h2>"),
    format("<div class='score'><b>~w of ~w criteria met</b><div class='track'><div class='fill' style='width:~w%'></div></div></div>~n", [Ok, Tot, Pct]),
    w("<div class='clist'>"),
    forall(criterion(K, Label),
           (   (   known(passed, K) -> Cls = pass, Ic = '&#10003;', Tx = 'Passed'
               ;   K == travel, known(referral, _) -> Cls = warn, Ic = '?', Tx = 'Ask NBTS staff'
               ;   Cls = fail, Ic = '&#10007;', Tx = 'Not met' ),
               format("<div class='citem ~w'><div class='cbox'>~w</div><div class='lbl'><span class='tag'>~w</span>~w</div></div>~n",
                      [Cls, Ic, Tx, Label]) )),
    w("</div></div>").

advice_box :-
    w("<div class='card'><h2>Recommendations</h2><ul>"),
    forall(known(advice, A), ( esc(A, Q), format("<li>~w</li>~n", [Q]) )),
    w("</ul></div>").

explanation(S) :-
    w("<div class='card'><h2>How the system reached this conclusion</h2>"),
    w("<div class='step'><div class='n'>1</div><b>Facts</b> (your answers)<br>"),
    forall(( attribute(A, L), known(A, V) ),
           ( esc(V, QV), format("<span class='pill'>~w: <b>~w</b></span>~n", [L, QV]) )),
    w("</div><div class='step'><div class='n'>2</div><b>Rules applied</b> (forward chaining, in firing order)"),
    forall(fired(Id), show_rule(Id)),
    w("</div><div class='step'><div class='n'>3</div><b>Backward-chaining proof</b> of the conclusion"),
    w("<details><summary>Show proof tree</summary><p><small>Starting from the conclusion, the system finds the rule that could produce it and proves each condition.</small></p>"),
    (   bc(status = S, Proof)
    ->  with_output_to(string(Str), print_proof(Proof, 0)),
        esc(Str, Q), format("<pre>~w</pre>~n", [Q])
    ;   w("<p>Proof failed.</p>")
    ),
    w("</details></div></div>"),
    w("<div class='acts'><a class='btn' href='/'>Check another donor</a> <button class='ghost' onclick='window.print()'>Print result</button></div>").

show_rule(Id) :-
    rule(Id, _, Conds, A = V, Src), source(Src, ST),
    format("<div class='rulebox'><b>Rule ~w</b><br>IF<ul>", [Id]),
    forall(member(C, Conds), ( cond_text(C, T), esc(T, Q), format("<li>~w</li>~n", [Q]) )),
    esc(V, QV),
    link_text(ST, STH),
    format("</ul>THEN <code>~w = ~w</code><br><small>Source: ~w</small></div>~n", [A, QV, STH]).

%% src_link(+Key, -Html): the source key as a link to its URL (plain key if no URL).
src_link(Key, Html) :-
    (   source(Key, T), format(atom(A), "~w", [T]), once(sub_atom(A, B, _, _, 'https://'))
    ->  sub_atom(A, B, _, 0, Url), esc(Url, QU),
        format(atom(Html), "<a href='~w' target='_blank' rel='noopener'>~w</a>", [QU, Key])
    ;   format(atom(Html), "~w", [Key])
    ).

%% ---------------- Knowledge base page ----------------
page_rules(_Request) :-
    page_start('Knowledge Base'),
    w("<div class='card'><h2>Rules</h2><input class='search' id='q' type='search' placeholder='Search rules by id, condition or source...' oninput='flt()'><div class='twrap'><table id='rt'><tr><th>ID</th><th>Stratum</th><th>IF</th><th>THEN</th><th>Source</th></tr>"),
    forall(rule(Id, S, Conds, A = V, Src),
           ( format(atom(CT), "~w", [Conds]), esc(CT, QC), esc(V, QV),
             src_link(Src, SL),
             format("<tr><td>~w</td><td><span class='badge'>~w</span></td><td>~w</td><td>~w = ~w</td><td>~w</td></tr>~n",
                    [Id, S, QC, A, QV, SL]) )),
    w("</table></div></div>"),
    w("<script>function flt(){var t=document.getElementById('q').value.toLowerCase(),r=document.querySelectorAll('#rt tr');for(var k=1;k<r.length;k++){r[k].style.display=r[k].textContent.toLowerCase().indexOf(t)<0?'none':''}}</script>"),
    w("<div class='card'><h2>Sources</h2><ul>"),
    forall(source(K, T), ( link_text(T, Q), format("<li><b>~w</b>: ~w</li>~n", [K, Q]) )),
    w("</ul></div>"),
    aggregate_all(count, malaria_endemic(_), N),
    aggregate_all(count, rule(_, _, _, _, _), NR),
    format("<div class='card'><h2>Statistics</h2><p>Rules: ~w &nbsp;|&nbsp; Malaria-endemic country facts: ~w &nbsp;|&nbsp; Deferral-reason facts: 13 &nbsp;|&nbsp; Input attribute facts: 13</p></div>~n", [NR, N]),
    page_end.

page_tests(_Request) :-
    page_start('Test Cases'),
    w("<div class='card'><h2>Test cases (expected vs actual)</h2>"),
    w("<div id='sum' class='summary'></div><div class='twrap'><table id='tt'><tr><th>#</th><th>Scenario</th><th>Expected</th><th>Actual</th><th>Rules that fired</th><th>Result</th></tr>"),
    forall(case(N, Desc, _, ES, ED),
           (   run_case(N, AS, AD, Fired),
               msort(ED, EDs),
               (   ( AS == ES, AD == EDs ) -> R = "<span class='pass'>PASS</span>" ; R = "<span class='fail'>FAIL</span>" ),
               exclude([X]>>sub_atom(X, 0, 1, _, a), Fired, Shown),
               format("<tr><td>~w</td><td>~w</td><td>~w ~w</td><td>~w ~w</td><td>~w</td><td>~w</td></tr>~n",
                      [N, Desc, ES, ED, AS, AD, Shown, R])
           )),
    w("</table></div><p><small>Recommendation rules (a01-a09) fire for every eligible case and are omitted from the list.</small></p></div>"),
    w("<script>var p=document.querySelectorAll('#tt .pass').length,f=document.querySelectorAll('#tt .fail').length,s=document.getElementById('sum');s.textContent=p+' of '+(p+f)+' test cases passed';s.className='summary '+(f?'bad':'ok')</script>"),
    explanation_tests_card,
    page_end.

%% second card: tests of the reasoning (backward-chaining proof tree)
explanation_tests_card :-
    w("<div class='card'><h2>Explanation tests (backward-chaining proof)</h2>"),
    w("<p><small>For every scenario the system proves the expected status by backward chaining and checks: (1) the proof starts with the same final-decision rule that forward chaining fired, (2) the deferral rules used in the proof are among the rules that fired, (3) the other two statuses cannot be proved.</small></p>"),
    w("<div id='sum2' class='summary'></div><div class='twrap'><table id='te'><tr><th>#</th><th>Scenario</th><th>Proof root</th><th>Deferral rules in proof</th><th>Deferral rules fired</th><th>Wrong status blocked</th><th>Proof tree</th><th>Result</th></tr>"),
    forall(case(N, Desc, _, ES, _),
           (   (   explain_case(N, Ok, info(Root, PD, FD, WB)) -> true
               ;   Ok = fail, Root = none, PD = [], FD = [], WB = no ),
               (   Ok == pass -> R = "<span class='pass'>PASS</span>" ; R = "<span class='fail'>FAIL</span>" ),
               (   run_case(N, _, _, _), bc(status = ES, Proof)
               ->  with_output_to(string(Str), print_proof(Proof, 0)), esc(Str, Q)
               ;   Q = 'no proof' ),
               format("<tr><td>~w</td><td>~w</td><td>~w</td><td>~w</td><td>~w</td><td>~w</td><td><details><summary>show</summary><pre>~w</pre></details></td><td>~w</td></tr>~n",
                      [N, Desc, Root, PD, FD, WB, Q, R])
           )),
    w("</table></div></div>"),
    w("<script>var p2=document.querySelectorAll('#te .pass').length,f2=document.querySelectorAll('#te .fail').length,s2=document.getElementById('sum2');s2.textContent=p2+' of '+(p2+f2)+' explanation tests passed';s2.className='summary '+(f2?'bad':'ok')</script>").

